insert into feh.skills (wiki_name,name,group_name,tag_id,scategory,use_range,refine_path,description,required,next,exclusive,sp,can_use_move,can_use_weapon,might,stat_modifiers,cooldown,weapon_effectiveness,properties) values
  ('Odd Spd Wave 4','Odd Spd Wave 4','Odd Spd Wave','SID_速さの波・奇数4','passivec',null,null,'At start of turn, grants Spd+6 to unit and allies within 2 spaces of unit for 1 turn.<br><br>If unit''s Spd ≥ foe''s Spd-5, neutralizes effects that guarantee foe''s follow-up attacks and effects that prevent unit''s follow-up attacks during combat.<br><br>If it is an odd-numbered turn, grants Spd+6 to unit during combat.','Odd Spd Wave 3',null,false,300,'Infantry,  Armored,  Cavalry,  Flying','Red Sword,  Blue Lance,  Green Axe,  Red Bow,  Blue Bow,  Green Bow,  Colorless Bow,  Red Dagger,  Blue Dagger,  Green Dagger,  Colorless Dagger,  Red Tome,  Blue Tome,  Green Tome,  Colorless Tome,  Colorless Staff,  Red Breath,  Blue Breath,  Green Breath,  Colorless Breath,  Red Beast,  Blue Beast,  Green Beast,  Colorless Beast',null,'0,0,0,0,0',null,null,'random_inherit_base,random_all'),
  ('Odd Tempest 1','Odd Tempest 1','Odd Tempest','SID_迅雷風烈・奇数1','passivec',null,null,'At start of odd-numbered turns, if unit''s HP = 100%, unit can move 1 extra space. (That turn only. Does not stack.)',null,'Odd Tempest 2',false,60,'Infantry,Flying','Red Sword,  Blue Lance,  Green Axe,  Red Breath,  Blue Breath,  Green Breath,  Colorless Breath,  Red Beast,  Blue Beast,  Green Beast,  Colorless Beast',null,'0,0,0,0,0',null,null,'random_inherit_base,random_owner'),
  ('Odd Tempest 2','Odd Tempest 2','Odd Tempest','SID_迅雷風烈・奇数2','passivec',null,null,'At start of odd-numbered turns, if unit''s HP ≥ 50%, unit can move 1 extra space. (That turn only. Does not stack.)','Odd Tempest 1','Odd Tempest 3',false,120,'Infantry,Flying','Red Sword,  Blue Lance,  Green Axe,  Red Breath,  Blue Breath,  Green Breath,  Colorless Breath,  Red Beast,  Blue Beast,  Green Beast,  Colorless Beast',null,'0,0,0,0,0',null,null,'random_inherit_base,random_owner'),
